import { Dialog } from "./Dialog";
import * as table from "./Table";
import { getOppositeString, isLangRu, loadSortableJs, myParseInt, toastSuccess } from "./Light";

declare var Sortable: any;

let dialog: Dialog,
    $shownUl: JQuery,
    $hiddenUl: JQuery,
    $layoutsDefault: JQuery,
    $layoutsUser: JQuery,
    $newLayoutInput: JQuery,
    $filter: JQuery,
    $btnSaveLayout: JQuery;

export interface Layout {
    name: string;
    fieldKeys: string[];
}

export interface Field {
    key: string;
    name: string;
    title: string;
    width: string;
}

export type FieldsWidth = { [key: string]: string };

export type DialogSubmitCallback = (shownFieldKeys: string[], fieldsWidth?: FieldsWidth) => void;

interface CurrentState {
    tableName: string;
    layouts: Layout[];
    allFields: Field[];
    initialShownFieldKeys: string[];
    dialogSubmitCallback: DialogSubmitCallback | null;
    showFieldsWidth: boolean;
}

let currentState: CurrentState = {
    tableName: "",
    layouts: [],
    allFields: [],
    initialShownFieldKeys: [],
    dialogSubmitCallback: null,
    showFieldsWidth: false
};

/**
 * Эта функция вызывается всего один раз при первом клике на любую кнопку Table layout settings
 */
function initDialogListeners() {
    $btnSaveLayout = $("#tablelayoutdialog__btnsave").on("click", (e: any) => {
        e.preventDefault();
        const layoutName = $newLayoutInput.val();
        if (layoutName == "") {
            //нельзя сохранять настройку с пустым именем
            return;
        }
        ajaxCore({
            layoutName: layoutName,
            fieldsShow: getShownFieldKeys().join("|"),
            fieldsWidth: getFieldsWidth()
        }).done(() => {
            const successText = isLangRu ? "Настройки сохранены" : "Layout saved";
            toastSuccess(`${successText}: <strong>${layoutName}</strong>`);
        });
    });

    $newLayoutInput = $("#tablelayoutdialog__newlayout"); //.on('key', userLayoutSaveByEnter, 'enter');

    $("#tablelayoutdialog__linkall").on("click", (e: any) => {
        e.preventDefault();
        updateSortables(currentState.allFields.map(f => f.key));
    });
    $("#tablelayoutdialog__linknone").on("click", (e: any) => {
        e.preventDefault();
        updateSortables([]);
    });

    $layoutsDefault = $("#tablelayoutdialog__layoutsdefault").on("click", "a", (e: any) => {
        e.preventDefault();
        const layoutIndex = myParseInt((<HTMLAnchorElement>e.currentTarget).hash.substring(1));
        const fieldsShow = currentState.layouts[layoutIndex].fieldKeys;
        updateSortables(fieldsShow);
    });

    $layoutsUser = $("#tablelayoutdialog__layoutsuser")
        .on("click", "a", (e: any) => {
            e.preventDefault();
            const a = <HTMLAnchorElement>e.currentTarget;
            $newLayoutInput.val(a.innerText);
            updateSortables(a.hash.substring(1).split("|"));
        })
        .on("click", "i", (e: any) => {
            ajaxCore({ delid: (<HTMLElement>e.currentTarget).getAttribute("data-delid") });
        });

    //$shownUl = $("#tablelayoutdialog__showul").sortable({ connectWith: "#tablelayoutdialog__hideul" });
    //$hiddenUl = $("#tablelayoutdialog__hideul").sortable({ connectWith: "#tablelayoutdialog__showul" });
    $shownUl = $("#tablelayoutdialog__showul");
    $hiddenUl = $("#tablelayoutdialog__hideul");

    $filter = $("#tablelayoutdialog__filter").on("keyup change", (e: any) => {
        const filterLower = (<HTMLInputElement>e.currentTarget).value.toLowerCase();
        if (filterLower === "") {
            $hiddenUl.find("li.display-none").removeClass("display-none");
        } else {
            const filterLowerOpposite = getOppositeString(filterLower);
            $hiddenUl.find("li").each(function(this: HTMLLIElement) {
                const $li = $(this);
                const currentTextLower = $li.text().toLowerCase();
                const currentTitleLower = ($li.attr("title") || "").toLowerCase();
                const hide =
                    currentTextLower.indexOf(filterLower) === -1 &&
                    currentTextLower.indexOf(filterLowerOpposite) === -1 &&
                    currentTitleLower.indexOf(filterLower) === -1 &&
                    currentTitleLower.indexOf(filterLowerOpposite) === -1;

                $li.toggleClass("display-none", hide);
            });
        }
    });

    loadSortableJs().then(() => {
        Sortable.create(document.getElementById("tablelayoutdialog__showul"), {
            group: "tbl",
            animation: 100
        });
        Sortable.create(document.getElementById("tablelayoutdialog__hideul"), {
            group: "tbl",
            animation: 100
        });
    });
}

function updateSortables(showFieldKeys: string[]) {
    //Очистим оба списка в DOM
    $filter.val("");
    $shownUl.empty();
    $hiddenUl.empty();

    // Перебираем все поля и добавляем их либо в блок отображаемых, либо в блок скрытых
    // Подготовим накопительный массив полей, которые потом будут отрендрены в блок отображаемых в нужном порядке
    let toShow: Field[] = [];
    currentState.allFields.forEach(field => {
        // Определим позицию в блоке Shown в которую вставить текущее поле
        const showIndex = showFieldKeys.indexOf(field.key);
        if (showIndex === -1) {
            // Этого поля нет в массиве отображаемых, сразу вставляем его в список скрытых полей
            appendLi($hiddenUl, field.key, field.name, field.title, field.width);
        } else {
            // Определили позицию под которой нужно вставить в блок отображаемых полей. Но сразу вставлять в DOM не будем, накопим
            // в подготовительном массиве
            toShow[showIndex] = field;
        }
    });

    // Отрендрим накопленный массив отображаемых полей
    toShow.forEach(field => appendLi($shownUl, field.key, field.name, field.title, field.width));
}

const appendLi = function($ul: JQuery, fieldKey: string, fieldName: string, fieldTitle: string, fieldWidth?: string) {
    //С помощью css класса подсветим поле фиолетовым или голубым
    const cssClass =
        currentState.initialShownFieldKeys.indexOf(fieldKey) === -1
            ? "tablelayoutdialog__field_hidden"
            : "tablelayoutdialog__field_shown";

    if (!fieldWidth) {
        fieldWidth = "";
    }

    const innerHtml = currentState.showFieldsWidth
        ? `<div><div>${fieldName}</div><div><input type="number" name="${fieldKey}" value="${fieldWidth}" title="Ширина"></div></div>`
        : fieldName;

    $("<li>")
        .html(innerHtml)
        .attr("data-fieldkey", fieldKey)
        .attr("title", fieldTitle)
        .addClass(cssClass)
        .appendTo($ul);
};

/**
 * Возвращает массив из ключей полей, которые сейчас находятся в левом блоке (в блоке отображаемы)
 * Этот метод вызывается при сабмите диалога и при сохранении пользовательских настроек
 */
function getShownFieldKeys(): string[] {
    const shownFieldKeys: string[] = [];
    $shownUl.find("li").each(function(this: HTMLLIElement) {
        shownFieldKeys.push(this.getAttribute("data-fieldkey")!);
    });
    return shownFieldKeys;
}

function getFieldsWidth(): FieldsWidth {
    const result: FieldsWidth = {};
    $shownUl
        .add($hiddenUl)
        .find("input[type=number]")
        .each(function(this: HTMLInputElement) {
            result[this.name] = this.value;
        });
    return result;
}

function ajaxCore(postdata?: Object) {
    const url = "?a=Core&ps=table&table=" + currentState.tableName;
    $btnSaveLayout.prop("disabled", true);

    return $.ajax(url, <JQuery.AjaxSettings>{
        cache: false,
        data: postdata,
        type: "post"
    })
        .done((userLayoutsHtml: string) => {
            // В ответ всегда приходит html код для вставки в виде списка пользовательских layouts
            $layoutsUser.html(userLayoutsHtml);
        })
        .always(() => {
            $btnSaveLayout.prop("disabled", false);
        });
}

/**
 * Этот метод специально сделан экспортируемым, чтобы можно было отображать диалоговое окно выбора полей
 * не только по стандартной ссылке "Table layout settings", но и в SPA приложении
 */
export function showLayoutDialog(
    tableName: string,
    allFields: Field[],
    initialShownFieldKeys: string[],
    layouts: Layout[],
    bodyHtml: string,
    dialogSubmitCallback: DialogSubmitCallback,
    showFieldsWidth: boolean = false
) {
    const options = {
        width: "870px",
        buttonOkText: isLangRu ? "Применить" : "Apply new Layout",
        buttonCancelText: isLangRu ? "Отмена" : "Cancel",
        buttonOkHandler: () => {
            dialog.close();
            currentState.dialogSubmitCallback!(getShownFieldKeys(), getFieldsWidth());
        }
    };

    dialog = new Dialog(bodyHtml, options);

    currentState.showFieldsWidth = showFieldsWidth;
    currentState.tableName = tableName;
    currentState.allFields = allFields;
    currentState.initialShownFieldKeys = initialShownFieldKeys;
    currentState.layouts = layouts;
    currentState.dialogSubmitCallback = dialogSubmitCallback;

    // Отобразим диалог
    dialog.open();

    initDialogListeners();

    updateSortables(initialShownFieldKeys);

    // Отрендрим блок с layouts default
    $layoutsDefault.empty();
    currentState.layouts.forEach((layout, index) => {
        $layoutsDefault.append(`<li><a href="#${index}">${layout.name}</a></li>`);
    });

    $newLayoutInput.val("");
}

// На все кнопки Table Layout Settings вешаем обрабочик клика
$("body").on("click", "a.table-layoutsettings", (e: any) => {
    e.preventDefault();
    const tableName: string = $(e.currentTarget)
        .closest("div.table-div")
        .attr("data-tablename")!;
    const tableObj = table.get(tableName);
    $.ajax(tableObj.reloadUrl + "&loadTableLayoutSettings=1").done((settingsFromServer: any) => {
        const { allFields, shownFieldKeys, layouts, bodyHtml } = settingsFromServer;
        const dialogSubmitCallback = (shownFieldKeys: string[], fieldsWidth: FieldsWidth) => {
            tableObj.reload({ fieldsShow: shownFieldKeys.join("|"), fieldsWidth: fieldsWidth });
        };
        showLayoutDialog(tableName, allFields, shownFieldKeys, layouts, bodyHtml, dialogSubmitCallback, true);
    });
});
